/** What a caller needs to reach the Page-Flow agent on this computer. */
export interface PageFlowSettings {
    /** The plain HTTP port. */
    port: number;
    /** The HTTPS port. The agent serves HTTPS with a certificate the installer trusts for this user. */
    httpsPort: number;
    /** True to call the agent over HTTPS. False calls the plain HTTP port. */
    useHttps: boolean;
    pairingToken: string;
}

export const PAGE_FLOW_DEFAULT_PORT = 52180;
export const PAGE_FLOW_DEFAULT_HTTPS_PORT = 52181;
/** The agent listens on loopback only, so the host is fixed. */
export const PAGE_FLOW_HOST = '127.0.0.1';

export const DEFAULT_PAGE_FLOW_SETTINGS: Readonly<PageFlowSettings> = {
    port: PAGE_FLOW_DEFAULT_PORT,
    httpsPort: PAGE_FLOW_DEFAULT_HTTPS_PORT,
    useHttps: true,
    pairingToken: '',
};

export function isValidPageFlowPort(value: unknown): value is number {
    return Number.isInteger(value) && (value as number) >= 1 && (value as number) <= 65535;
}

export function pageFlowBaseUrl(port: number): string {
    return `http://${PAGE_FLOW_HOST}:${port}`;
}

export function pageFlowHttpsBaseUrl(port: number): string {
    return `https://${PAGE_FLOW_HOST}:${port}`;
}

/** The base URL the client calls: HTTPS when chosen, otherwise plain HTTP. */
export function pageFlowConnectionUrl(settings: Pick<PageFlowSettings, 'port' | 'httpsPort' | 'useHttps'>): string {
    return settings.useHttps ? pageFlowHttpsBaseUrl(settings.httpsPort) : pageFlowBaseUrl(settings.port);
}

/**
 * Reads settings saved as JSON. A missing, unreadable or invalid value falls back to the defaults,
 * so the client always has usable ports. The caller decides where the text comes from.
 */
export function parsePageFlowSettings(raw: string | null): PageFlowSettings {
    if (!raw) {
        return { ...DEFAULT_PAGE_FLOW_SETTINGS };
    }
    let parsed: Partial<PageFlowSettings> | null;
    try {
        parsed = JSON.parse(raw) as Partial<PageFlowSettings> | null;
    } catch {
        return { ...DEFAULT_PAGE_FLOW_SETTINGS };
    }
    const port = isValidPageFlowPort(parsed?.port) ? (parsed?.port as number) : DEFAULT_PAGE_FLOW_SETTINGS.port;
    const savedHttpsPort = isValidPageFlowPort(parsed?.httpsPort) ? (parsed?.httpsPort as number) : undefined;
    // The two ports must differ. A saved HTTPS port that matches the HTTP port falls back to a default that does not.
    const fallbackHttps =
        port === DEFAULT_PAGE_FLOW_SETTINGS.httpsPort ? DEFAULT_PAGE_FLOW_SETTINGS.port : DEFAULT_PAGE_FLOW_SETTINGS.httpsPort;
    const httpsPort = savedHttpsPort !== undefined && savedHttpsPort !== port ? savedHttpsPort : fallbackHttps;
    const useHttps = typeof parsed?.useHttps === 'boolean' ? parsed.useHttps : DEFAULT_PAGE_FLOW_SETTINGS.useHttps;
    const pairingToken = parsed?.pairingToken;
    return {
        port,
        httpsPort,
        useHttps,
        pairingToken: typeof pairingToken === 'string' ? pairingToken : '',
    };
}

/** Turns settings into the JSON text to store. Throws a RangeError for ports that are invalid or equal. */
export function serializePageFlowSettings(settings: PageFlowSettings): string {
    if (!isValidPageFlowPort(settings.port) || !isValidPageFlowPort(settings.httpsPort)) {
        throw new RangeError('The ports must be whole numbers from 1 to 65535.');
    }
    if (settings.port === settings.httpsPort) {
        throw new RangeError('The HTTP and HTTPS ports must be different.');
    }
    return JSON.stringify({
        port: settings.port,
        httpsPort: settings.httpsPort,
        useHttps: settings.useHttps === true,
        pairingToken: settings.pairingToken.trim(),
    });
}
