// Synced from the Page-Flow repository (sdk/src). Edit it there, then run npm run sync:sdk.
import { PageFlowError } from './error';
import { PageFlowSettings, pageFlowConnectionUrl } from './settings';
import {
    PageFlowDevice,
    PageFlowDeviceList,
    PageFlowHealth,
    PageFlowPrintJob,
    PageFlowPrintOptions,
    PageFlowRefreshResult,
    PageFlowScanContentType,
    PageFlowScanOptions,
    PageFlowScanResult,
    PageFlowSessionPages,
} from './models';

export type PageFlowFetch = (url: string, init: RequestInit) => Promise<Response>;

export interface PageFlowClientOptions {
    /** Read on every call, so a changed port or token applies without restarting the client. */
    settings: () => PageFlowSettings;
    /** Defaults to the global fetch. Replace it in tests or to add logging. */
    fetch?: PageFlowFetch;
    /** Longer than the agent's own scan timeout (180 s), so a slow scan is not cut off here first. */
    timeoutMs?: number;
}

export const DEFAULT_REQUEST_TIMEOUT_MS = 240_000;

const JSON_TYPE = 'application/json';
const PDF_TYPE = 'application/pdf';
const SCAN_TYPES: readonly PageFlowScanContentType[] = ['image/jpeg', 'application/pdf'];

interface AgentFailureBody {
    code?: unknown;
    message?: unknown;
    retryable?: unknown;
}

interface SendOptions {
    json?: unknown;
    body?: BodyInit;
    contentType?: string;
    signal?: AbortSignal;
}

/**
 * Calls the Page-Flow agent on this computer. Every call is a `/v1` route, sent with the pairing
 * token from the settings. Nothing is retried: a failed scan or print is reported to the caller,
 * which decides what happens next.
 */
export class PageFlowClient {
    private readonly settings: () => PageFlowSettings;
    private readonly fetcher: PageFlowFetch;
    private readonly timeoutMs: number;

    constructor(options: PageFlowClientOptions) {
        this.settings = options.settings;
        this.fetcher = options.fetch ?? ((url, init) => fetch(url, init));
        this.timeoutMs = options.timeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS;
    }

    health(signal?: AbortSignal): Promise<PageFlowHealth> {
        return this.getJson('/v1/health', signal);
    }

    async scanners(signal?: AbortSignal): Promise<PageFlowDevice[]> {
        return devicesFrom(await this.getJson<PageFlowDeviceList>('/v1/scanners', signal));
    }

    async printers(signal?: AbortSignal): Promise<PageFlowDevice[]> {
        return devicesFrom(await this.getJson<PageFlowDeviceList>('/v1/printers', signal));
    }

    refresh(signal?: AbortSignal): Promise<PageFlowRefreshResult> {
        return this.postJson('/v1/refresh', undefined, signal);
    }

    /** One scan of one page. The reply is the page itself, JPEG or PDF. */
    async scan(options: PageFlowScanOptions, signal?: AbortSignal): Promise<PageFlowScanResult> {
        const response = await this.send('POST', '/v1/scan', { json: options, signal });
        return this.scanResult(response);
    }

    async startScanSession(signal?: AbortSignal): Promise<string> {
        const reply = await this.postJson<{ session_id: string }>('/v1/scan/sessions', undefined, signal);
        if (typeof reply?.session_id !== 'string') {
            throw invalidResponse(200);
        }
        return reply.session_id;
    }

    /** Scans one page into an open session. Resolves to the number of pages now in the session. */
    async addScanPage(sessionId: string, options: PageFlowScanOptions, signal?: AbortSignal): Promise<number> {
        const reply = await this.postJson<PageFlowSessionPages>(
            sessionPath(sessionId, 'pages'),
            options,
            signal,
        );
        if (typeof reply?.pages !== 'number') {
            throw invalidResponse(200);
        }
        return reply.pages;
    }

    /** Builds one PDF from the session's pages. The session stays open if this fails. */
    async finishScanSession(sessionId: string, signal?: AbortSignal): Promise<Blob> {
        const response = await this.send('POST', sessionPath(sessionId, 'finish'), { signal });
        if (mediaType(response.headers.get('Content-Type')) !== PDF_TYPE) {
            throw invalidResponse(response.status);
        }
        return response.blob();
    }

    async cancelScanSession(sessionId: string, signal?: AbortSignal): Promise<void> {
        await this.send('POST', sessionPath(sessionId, 'cancel'), { signal });
    }

    /**
     * Sends a PDF to a printer. Once the request is sent, any failure other than a refusal the
     * agent gave in a well-formed reply is reported as `print_outcome_unknown`: the printer may
     * already have the job, so the caller must check the queue rather than print again.
     */
    async print(
        document: Blob | ArrayBuffer,
        options: PageFlowPrintOptions,
        signal?: AbortSignal,
    ): Promise<PageFlowPrintJob> {
        try {
            const response = await this.send('POST', `/v1/print?${printQuery(options)}`, {
                body: document,
                contentType: PDF_TYPE,
                signal,
            });
            return await this.readJson<PageFlowPrintJob>(response);
        } catch (error) {
            throw printFailure(error);
        }
    }

    printJob(jobId: string, printerId: string, signal?: AbortSignal): Promise<PageFlowPrintJob> {
        return this.getJson(jobPath(jobId, printerId), signal);
    }

    cancelPrintJob(jobId: string, printerId: string, signal?: AbortSignal): Promise<PageFlowPrintJob> {
        return this.postJson(`${jobPath(jobId, printerId)}/cancel`, undefined, signal);
    }

    private async getJson<T>(path: string, signal?: AbortSignal): Promise<T> {
        return this.readJson<T>(await this.send('GET', path, { signal }));
    }

    private async postJson<T>(path: string, json: unknown, signal?: AbortSignal): Promise<T> {
        return this.readJson<T>(await this.send('POST', path, { json, signal }));
    }

    private async send(method: 'GET' | 'POST', path: string, options: SendOptions): Promise<Response> {
        const { baseUrl, token } = this.connection();
        const headers = new Headers({ Authorization: `Bearer ${token}` });
        const body = options.json !== undefined ? JSON.stringify(options.json) : options.body;
        if (options.json !== undefined) {
            headers.set('Content-Type', JSON_TYPE);
        }
        if (options.contentType) {
            headers.set('Content-Type', options.contentType);
        }

        const response = await this.dispatch(
            `${baseUrl}${path}`,
            // Redirects are refused, so the pairing token is never sent to another address.
            { method, headers, body, redirect: 'error' },
            options.signal,
        );
        if (!response.ok) {
            throw await failureFrom(response);
        }
        return response;
    }

    /**
     * Sends one request with a timeout. A caller's abort passes through as the caller's own error.
     * A timeout or a failed connection is reported as a Page-Flow error with status 0.
     */
    private async dispatch(url: string, init: RequestInit, signal?: AbortSignal): Promise<Response> {
        const controller = new AbortController();
        let timedOut = false;
        const timer = setTimeout(() => {
            timedOut = true;
            controller.abort();
        }, this.timeoutMs);
        const forwardAbort = (): void => controller.abort();
        signal?.addEventListener('abort', forwardAbort);
        try {
            return await this.fetcher(url, { ...init, signal: controller.signal });
        } catch (error) {
            if (signal?.aborted) {
                throw error;
            }
            if (timedOut) {
                throw new PageFlowError('agent_timeout', 'The Page-Flow agent took too long to answer.', true, 0, error);
            }
            throw new PageFlowError(
                'agent_unreachable',
                'The Page-Flow agent did not answer. Check that it is running on this computer.',
                true,
                0,
                error,
            );
        } finally {
            clearTimeout(timer);
            signal?.removeEventListener('abort', forwardAbort);
        }
    }

    private connection(): { baseUrl: string; token: string } {
        const settings = this.settings();
        const token = settings.pairingToken.trim();
        if (!token) {
            throw new PageFlowError('not_paired', 'Add the Page-Flow pairing token in the settings.', false, 0);
        }
        return { baseUrl: pageFlowConnectionUrl(settings), token };
    }

    private async readJson<T>(response: Response): Promise<T> {
        try {
            return (await response.json()) as T;
        } catch {
            throw invalidResponse(response.status);
        }
    }

    private async scanResult(response: Response): Promise<PageFlowScanResult> {
        const contentType = mediaType(response.headers.get('Content-Type'));
        if (!isScanContentType(contentType)) {
            throw invalidResponse(response.status);
        }
        return { blob: await response.blob(), contentType };
    }
}

function sessionPath(sessionId: string, action: 'pages' | 'finish' | 'cancel'): string {
    return `/v1/scan/sessions/${encodeURIComponent(sessionId)}/${action}`;
}

function jobPath(jobId: string, printerId: string): string {
    const query = new URLSearchParams({ printer_id: printerId });
    return `/v1/print/${encodeURIComponent(jobId)}?${query.toString()}`;
}

function printQuery(options: PageFlowPrintOptions): string {
    const query = new URLSearchParams();
    const optional: Record<string, string | number | undefined> = {
        printer_id: options.printer_id,
        copies: options.copies,
        colour: options.colour,
        orientation: options.orientation,
        paper: options.paper,
        quality: options.quality,
    };
    for (const [name, value] of Object.entries(optional)) {
        if (value !== undefined) {
            query.set(name, String(value));
        }
    }
    return query.toString();
}

/**
 * Once the print request has been sent, the printer may have the job whatever the reply looks like.
 * Only the no-token error (raised before anything is sent) and a refusal the agent gave in a
 * well-formed reply are passed on as they are. Everything else is an unknown outcome.
 */
function printFailure(error: unknown): unknown {
    if (error instanceof PageFlowError && (error.code === 'not_paired' || isAgentRefusal(error))) {
        return error;
    }
    return new PageFlowError(
        'print_outcome_unknown',
        'The Page-Flow agent did not confirm the print. Check the printer queue before printing again.',
        false,
        0,
        error,
    );
}

function isAgentRefusal(error: PageFlowError): boolean {
    return error.status > 0 && error.code !== 'invalid_response';
}

function devicesFrom(list: PageFlowDeviceList): PageFlowDevice[] {
    if (!Array.isArray(list?.devices)) {
        throw invalidResponse(200);
    }
    return list.devices;
}

async function failureFrom(response: Response): Promise<PageFlowError> {
    const body = (await response.json().catch(() => null)) as AgentFailureBody | null;
    if (!body || typeof body.code !== 'string') {
        return invalidResponse(response.status);
    }
    const message = typeof body.message === 'string' ? body.message : 'The agent refused the request.';
    return new PageFlowError(body.code, message, body.retryable === true, response.status);
}

function invalidResponse(status: number): PageFlowError {
    return new PageFlowError(
        'invalid_response',
        'The Page-Flow agent replied in a form the client does not understand.',
        false,
        status,
    );
}

function mediaType(header: string | null): string {
    return (header ?? '').split(';')[0].trim().toLowerCase();
}

function isScanContentType(value: string): value is PageFlowScanContentType {
    return (SCAN_TYPES as readonly string[]).includes(value);
}
